const loginView=document.querySelector('#loginView'),dashboard=document.querySelector('#dashboard'),toast=document.querySelector('#adminToast');
let bulletins=[];
const groupLabels={
  estado:['Estável','Apresenta melhora','Requer cuidados e acompanhamento','Estado delicado'],
  agua:['Bebeu normalmente','Bebeu pouco','Não bebeu espontaneamente'],
  fezes:['Sim','Normal','Não','Amolecido','Em observação','Diarreia'],
  comportamento:['Alerta/ativo','Tranquilo','Carinhoso/receptivo','Assustado/estressado','Sonolento','Em observação'],
  apetite:['Normal','Comeu pouco','Não quis comer'],alimentacao:['Ração seca','Ração úmida/pastosa','Dieta especial','Alimentação assistida'],
  urina:['Sim','Não','Em observação'],medicacao:['Medicações realizadas conforme prescrição'],frequencia:['1x ao dia','2x ao dia','3x ao dia','4x ao dia']
};
const groupTitles={estado:'Estado geral',agua:'Água',fezes:'Fezes',comportamento:'Comportamento',apetite:'Apetite',alimentacao:'Alimentação',urina:'Urina',medicacao:'Medicações',frequencia:'Frequência'};
const safe=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const formatDate=value=>{if(!value)return'Sem data';const date=new Date(`${String(value).slice(0,10)}T12:00:00`);return isNaN(date)?value:date.toLocaleDateString('pt-BR')};
const showToast=message=>{toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),2600)};
async function request(url,options={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(data.error||'Não foi possível concluir.'),{status:response.status});return data}
function showLogin(message=''){loginView.hidden=false;dashboard.hidden=true;document.querySelector('#loginError').textContent=message}
function showDashboard(){loginView.hidden=true;dashboard.hidden=false}
async function load(){try{const data=await request('/api/bulletins');bulletins=data.bulletins||[];showDashboard();render()}catch(error){if(error.status===401)showLogin();else showLogin(error.message)}}
document.querySelector('#loginForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;document.querySelector('#loginError').textContent='';try{await request('/api/auth/login',{method:'POST',body:JSON.stringify({user:document.querySelector('#loginUser').value,password:document.querySelector('#loginPassword').value})});await load()}catch(error){showLogin(error.message)}finally{button.disabled=false}});
document.querySelector('#logoutBtn').addEventListener('click',async()=>{await request('/api/auth/logout',{method:'POST'}).catch(()=>{});showLogin();document.querySelector('#loginForm').reset()});
function filtered(){const term=document.querySelector('#searchInput').value.trim().toLocaleLowerCase('pt-BR'),date=document.querySelector('#dateFilter').value,species=document.querySelector('#speciesFilter').value;return bulletins.filter(item=>{const haystack=`${item.data?.paciente||''} ${item.data?.tutor||''} ${item.data?.veterinario||''} ${item.responsavel||''}`.toLocaleLowerCase('pt-BR');return(!term||haystack.includes(term))&&(!date||String(item.data?.data||'').slice(0,10)===date)&&(!species||item.species===species)})}
function render(){const today=new Date().toISOString().slice(0,10);document.querySelector('#metricTotal').textContent=bulletins.length;document.querySelector('#metricToday').textContent=bulletins.filter(x=>String(x.data?.data||'').slice(0,10)===today).length;document.querySelector('#metricCanine').textContent=bulletins.filter(x=>x.species==='canina').length;document.querySelector('#metricFeline').textContent=bulletins.filter(x=>x.species==='felina').length;const items=filtered(),body=document.querySelector('#recordsBody'),empty=document.querySelector('#emptyState');body.innerHTML='';empty.hidden=Boolean(items.length);items.forEach(item=>{const tr=document.createElement('tr');tr.innerHTML=`<td><strong>${safe(formatDate(item.data?.data))}</strong><small>${safe(item.data?.horario||'Horário não informado')}</small></td><td><strong>${safe(item.data?.paciente||'Sem nome')}</strong><small>Tutor: ${safe(item.data?.tutor||'Não informado')}</small></td><td><span class="tag ${item.species==='felina'?'feline':''}">${item.species==='felina'?'🐱 Felina':'🐶 Canina'}</span><small>${item.shift==='manha'?'Manhã':'Tarde/noite'}</small></td><td>${safe(item.data?.veterinario||'—')}</td><td class="responsible">${safe(item.responsavel||'Não informado')}</td><td><small>${new Date(item.updatedAt).toLocaleString('pt-BR')}</small></td><td><div class="row-actions"><button data-view="${safe(item.id)}" title="Ver boletim">◉</button><button class="delete" data-delete="${safe(item.id)}" title="Excluir">×</button></div></td>`;body.appendChild(tr)});document.querySelector('#resultCount').textContent=`${items.length} ${items.length===1?'registro':'registros'}`}
['searchInput','dateFilter','speciesFilter'].forEach(id=>document.querySelector(`#${id}`).addEventListener('input',render));
document.querySelector('#clearFilters').addEventListener('click',()=>{document.querySelector('#searchInput').value='';document.querySelector('#dateFilter').value='';document.querySelector('#speciesFilter').value='';render()});
function answers(item,group){return groupLabels[group].filter((_,i)=>item.data?.[`${group}_${i}`])}
function openDetail(item){const sections=Object.keys(groupLabels).map(group=>{const selected=answers(item,group);return selected.length?`<section class="detail-section"><h3>${groupTitles[group]}</h3><div class="answer-list">${selected.map(value=>`<span>${safe(value)}</span>`).join('')}</div></section>`:''}).join('');document.querySelector('#detailContent').innerHTML=`<div class="detail-head"><p class="eyebrow">BOLETIM ${item.species==='felina'?'FELINO':'CANINO'}</p><h2>${safe(item.data?.paciente||'Paciente')}</h2><p>Registro interno realizado por <strong>${safe(item.responsavel||'Não informado')}</strong>.</p></div><div class="detail-grid"><div class="detail-field"><span>Tutor</span><strong>${safe(item.data?.tutor||'—')}</strong></div><div class="detail-field"><span>Data e horário</span><strong>${safe(formatDate(item.data?.data))} • ${safe(item.data?.horario||'—')}</strong></div><div class="detail-field"><span>Veterinário</span><strong>${safe(item.data?.veterinario||'—')}</strong></div><div class="detail-field"><span>Período</span><strong>${item.shift==='manha'?'Manhã':'Tarde/noite'}</strong></div></div>${sections}${item.data?.outros?`<section class="detail-section"><h3>Outras medicações</h3><p>${safe(item.data.outros)}</p></section>`:''}<section class="detail-section"><h3>Observações da equipe</h3><p>${safe(item.data?.observacoes||'Nenhuma observação registrada.')}</p></section>`;document.querySelector('#detailDialog').showModal()}
document.querySelector('#recordsBody').addEventListener('click',async event=>{const view=event.target.closest('[data-view]'),remove=event.target.closest('[data-delete]');if(view){const item=bulletins.find(x=>x.id===view.dataset.view);if(item)openDetail(item)}if(remove){const item=bulletins.find(x=>x.id===remove.dataset.delete);if(item&&confirm(`Excluir definitivamente o boletim de ${item.data?.paciente||'paciente'}?`)){try{await request('/api/bulletins',{method:'DELETE',body:JSON.stringify({id:item.id})});bulletins=bulletins.filter(x=>x.id!==item.id);render();showToast('Boletim excluído')}catch(error){showToast(error.message)}}}});
document.querySelector('#closeDetail').addEventListener('click',()=>document.querySelector('#detailDialog').close());
document.querySelector('#detailDialog').addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close()});
document.querySelector('#exportBtn').addEventListener('click',()=>{const items=filtered();if(!items.length)return showToast('Não há registros para exportar');const quote=v=>`"${String(v??'').replace(/"/g,'""')}"`,rows=[['Data','Horário','Animal','Tutor','Espécie','Período','Veterinário','Responsável','Registrado em'],...items.map(x=>[formatDate(x.data?.data),x.data?.horario||'',x.data?.paciente||'',x.data?.tutor||'',x.species==='felina'?'Felina':'Canina',x.shift==='manha'?'Manhã':'Tarde/noite',x.data?.veterinario||'',x.responsavel||'',new Date(x.updatedAt).toLocaleString('pt-BR')])],blob=new Blob(['\ufeff'+rows.map(row=>row.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`relatorio-boletins-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast('Relatório baixado')});
load();
